#!/usr/bin/env node
// Renders README.md and generated/deals.{json,csv} from data/deals/*.yaml.
// --check : exit 1 if README.md / generated files are out of date (used in CI). The date-dependent
//           "Ending soon" table is checked for genuine rows only, so it doesn't fail day to day.
import fs from 'node:fs';
import path from 'node:path';
import { loadDeals, ROOT, CATEGORY_META, todayISO } from './lib.mjs';

const CHECK = process.argv.includes('--check');
const deals = loadDeals().map((x) => x.deal).filter((d) => d.status !== 'expired');
const byCat = {};
for (const d of deals) (byCat[d.category] ||= []).push(d);
for (const k of Object.keys(byCat)) byCat[k].sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }));
const cats = Object.keys(CATEGORY_META).filter((c) => byCat[c]);
const lastVerified = deals.map((d) => d.verified_on).sort().at(-1) || todayISO();
const esc = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
const anchor = (c) => CATEGORY_META[c].title.toLowerCase().replace(/[^a-z0-9 -]/g, '').trim().replace(/\s+/g, '-');
const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const fmtDate = (s) => (s ? `${MON[+s.slice(5, 7) - 1]} ${+s.slice(8, 10)}` : '—');
const price = (d) => {
  if (d.deal_price == null) return '';
  const sym = { USD: '$', INR: '₹', EUR: '€', GBP: '£', CAD: 'C$', AUD: 'A$' }[d.currency] || '';
  const f = (n) => sym + Number(n).toLocaleString(d.currency === 'INR' ? 'en-IN' : 'en-US');
  return d.regular_price != null ? ` (${f(d.deal_price)}, was ${f(d.regular_price)})` : ` (${f(d.deal_price)})`;
};
const row = (d) => `| [${esc(d.name)}](${d.url}) | ${esc(d.deal_description)}${esc(price(d))} | ${d.coupon_code ? '`' + esc(d.coupon_code) + '`' : '—'} | ${fmtDate(d.end_date)} |`;
const HEAD = '| Deal | What you get | Code | Ends |\n|---|---|---|---|';

const endingSoon = deals.filter((d) => d.end_date && d.end_date >= todayISO()).sort((a, b) => a.end_date.localeCompare(b.end_date) || a.name.localeCompare(b.name)).slice(0, 15);

let md = `<!-- ⚠️ AUTO-GENERATED by scripts/build-readme.mjs from data/deals/*.yaml — DO NOT EDIT THIS FILE DIRECTLY. Edit the YAML and run \`npm run build\`. -->
# DealsDrop — Black Friday & Cyber Monday 2026 deals

**Verified deals, dropped as they go live.**

**Why DealsDrop is different**

- **Every deal is verified.** Each one was checked on the vendor's own official page and links straight to it. Deals expire automatically: a daily bot flags deals past their end date.
- **Zero affiliate links or paid placements**, enforced by CI on every pull request.
- **Open data.** The full list is published as [JSON](generated/deals.json) and [CSV](generated/deals.csv) with category, discount, code and end-date fields.
- **Year-round seasons are coming.** Black Friday and Cyber Monday are live now; Christmas, Diwali, Prime Day and lifetime deals are coming.

**${deals.length} verified deals across ${cats.length} categories** — software, AI, hosting, courses, gadgets, home, fashion, gaming, travel and streaming, from stores in the US, India and worldwide. No affiliate links, no tracking parameters, no paid placements.

[![Validate](https://github.com/nick-choudhary/dealsdrop/actions/workflows/validate.yml/badge.svg)](.github/workflows/validate.yml) ![Deals](https://img.shields.io/badge/deals-${deals.length}-black) ![Last verified](https://img.shields.io/badge/last_verified-${lastVerified.replace(/-/g, '--')}-informational) ![Affiliate links](https://img.shields.io/badge/affiliate_links-0-success) ![License](https://img.shields.io/badge/data-CC0--1.0-lightgrey)

> Black Friday is **Fri Nov 27, 2026** · Cyber Monday is **Mon Nov 30, 2026**. Every row links to the official vendor page. Prices change fast; check the final price at checkout.
>
> **Want to add a deal?** Read [CONTRIBUTING.md](CONTRIBUTING.md). Deals live in [\`data/deals/\`](data/deals) and are checked by CI. Raw data: [JSON](generated/deals.json) · [CSV](generated/deals.csv).

## Contents

| Category | Deals |
|---|---:|
${cats.map((c) => `| ${CATEGORY_META[c].emoji} [${CATEGORY_META[c].title}](#${anchor(c)}) | ${byCat[c].length} |`).join('\n')}
| ⏰ [Ending soon](#ending-soon) | ${endingSoon.length} |

## Ending soon

${HEAD}
${endingSoon.map(row).join('\n')}

`;
for (const c of cats) md += `## ${CATEGORY_META[c].title}\n\n${byCat[c].length} deals · sorted A–Z · [back to top](#contents)\n\n${HEAD}\n${byCat[c].map(row).join('\n')}\n\n`;
md += `## How this list stays clean\n\n- One YAML entry per deal, validated against [a JSON Schema](schema/deal.schema.json) on every pull request.\n- Links must be on the vendor's own domain. Tracking parameters (\`utm_*\`, \`ref\`, \`aff\`, \`via\`, \`tag\` …), link shorteners and affiliate networks are rejected.\n- Every deal must be confirmed on the vendor's own official page and needs a \`verified_on\` date and a GitHub handle. Vendors and employees must disclose.\n- Descriptions are capped at 160 characters; hype words, emoji, exclamation marks and ALL CAPS are rejected.\n- Max ${JSON.parse(fs.readFileSync(path.join(ROOT, 'config/rules.json'))).max_deals_per_vendor} deals per vendor (a short, maintainer-controlled list of big retailers such as Amazon and Flipkart may have up to 8, see [CONTRIBUTING](CONTRIBUTING.md#big-retailer-exception-to-the-3-per-vendor-cap)), duplicate detection, weekly link checks and a daily job that flags expired deals.\n\n## License\n\nThe deal data (\`data/\`, \`generated/\`) is released under [CC0-1.0](LICENSE-DATA). Code (\`scripts/\`, \`schema/\`, workflows) is [MIT](LICENSE). Trademarks belong to their owners. Not affiliated with any vendor listed.\n`;

const json = JSON.stringify({ generated_from: 'data/deals/*.yaml', count: deals.length, deals: [...deals].sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name)) }, null, 2) + '\n';
const cols = ['id', 'name', 'vendor', 'category', 'deal_description', 'discount_type', 'discount_value', 'coupon_code', 'regular_price', 'deal_price', 'currency', 'url', 'end_date', 'verified_on'];
const csvq = (v) => { const s = v == null ? '' : String(v); return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csv = [cols.join(','), ...JSON.parse(json).deals.map((d) => cols.map((c) => csvq(c === 'discount_type' ? d.discount.type : c === 'discount_value' ? d.discount.value : d[c])).join(','))].join('\n') + '\n';

// "Ending soon" depends on today's date, so the check masks it instead of comparing it byte for byte.
// Everything else must match exactly. Inside the masked part, every row must still be a row the builder
// would produce for a real deal (no hand edits), and the contents count must equal the number of rows.
const SOON_RE = /(## Ending soon\n\n[^\n]*\n[^\n]*\n)((?:\|[^\n]*\n)*)/;
const COUNT_RE = /(\| ⏰ \[Ending soon\]\(#ending-soon\) \| )(\d+)( \|)/;
const validRows = new Set(deals.map(row));
function readmeMatches(cur, fresh) {
  const mask = (t) => t.replace(SOON_RE, '$1<ending-soon>\n').replace(COUNT_RE, '$1N$3');
  if (mask(cur) !== mask(fresh)) return false;
  const m = cur.match(SOON_RE); const c = cur.match(COUNT_RE);
  if (!m || !c) return false;
  const rows = m[2].split('\n').filter(Boolean);
  return rows.length === Number(c[2]) && rows.every((r) => validRows.has(r));
}

const outputs = { 'README.md': md, 'generated/deals.json': json, 'generated/deals.csv': csv };
let stale = [];
for (const [f, content] of Object.entries(outputs)) {
  const p = path.join(ROOT, f);
  if (CHECK) {
    const cur = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
    const same = f === 'README.md' && cur != null ? readmeMatches(cur, content) : cur === content;
    if (!same) stale.push(f);
  }
  else { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, content); }
}
if (CHECK && stale.length) { console.log(`::error::Out of date: ${stale.join(', ')}. Run \`npm run build\` and commit the result (never edit README.md by hand).`); process.exit(1); }
console.log(CHECK ? 'README and generated files are up to date.' : `Wrote README.md + generated/ (${deals.length} deals, ${cats.length} categories).`);
